      "prompt": "（ジョンさんはたけしくんの中学校で英語を教えていました。つぎの文はジョンさんからたけしくんへのメールです。）\n\nたけしくん\nメール、ありがとう。前のメールに「英語の勉強はつまらない」と書いてありましたが、まず好きなことから始めたらどうですか。\nぼくが日本語の勉強を始めたのは中学1年のときです。友だちの家ではじめて日本のまんがを見ました。そのときは日本語がぜんぜんわからなかったのですが、えがあるから話はだいたいわかりました。日本語で読めるようになりたいと思って、自分で勉強を始めました。漢字は、難しかったですが、まんがを何さつも読んでいたら、かんたんな漢字はおぼえてしまいました。\nまんがはよくないと言う人もいますが、どんなものにもいいものと悪いものがあるとおもいます。だから、まんがもえらんで読めばいいと思います。人をいじめるようなまんがはよくないですが、サッカーやバスケットボールなどスポーツのまんがはおもしろいし、読むと元気になります。\nたけしくんは、何にきょうみがありますか。音楽ですか、映画ですか。（　　）じゃ、またメールします。\nジョン\n\n（　　）には何を入れますか。",
