    "meaning": {
      "prompt": "朝日市は、市民全員が力を合わせて美しい町を作り、気持ちのいい生活が送れるように新しい規則を作った。その規則では、次の三つのことを禁止している。①ゴミ箱などの決められた場所以外にゴミを捨てること、②歩きながらタバコを吸うこと、③指定の場所以外に自転車をとめること、である。守らなかった場合は、お金を払わされることもあるそうだ。\n\nこの規則について、正しいものはどれか。",
      "options": [
        "自分の家以外では、ゴミを捨ててはならない。",
        "道を歩きながら、タバコを吸ってはいけない。",
        "自転車は、決められた場所以外走ってはいけない。",
        "規則を守らない人は、全員お金を払わなければならない。"
      ],
      "answerIndex": 1
    },
    "optionExplanations": [
      "錯誤，原文規定的是「決められた場所以外にゴミを捨てること」禁止（不能丟在指定地點以外），並非「自己家以外都不能丟垃圾」。",
      "正確，原文規定「②歩きながらタバコを吸うこと」禁止，即不能邊走邊抽菸，符合選項描述。",
      "錯誤，原文規定的是「指定の場所以外に自転車をとめること」禁止（不能停在指定地點以外），選項卻說成「不能騎」，語意不符。",
      "錯誤，原文只說「違反規定的話，可能會被要求付錢」，並非「全員都必須付錢」。"
    ]
