    "meaning": {
      "prompt": "あなたのかいた絵が切手になります！\n 川田美術館の開館10年を記念して、記念切手を2種類発売します。そこで、切手に使用する絵を募集します。\n テーマは「平和」と「環境」の二つです。どちらかを選んで応募してください。\n 紙は指定の大きさ（20×25cm）のものを使ってください。絵の具、色えんぴつなど、何を使ってかいてもかまいません。\n 絵が選ばれた方には、5万円を差し上げます。\n 詳しくは美術館のホームページ（http://www.kawada.artor.jp）をご覧ください。\n\n川田美術館\n\n応募する人は、どうしなければならないか。",
      "options": [
        "「平和と環境」というテーマで絵をかいて送る。",
        "二つのテーマから一つ選んで絵をかいて送る。",
        "好きな大きさの紙に絵をかいて送る。",
        "決められた絵の具で絵をかいて送る。"
      ],
      "answerIndex": 1
    },
    "optionExplanations": [
      "錯誤，原文說明「平和」與「環境」是兩個不同主題，應「二選一」，並非合併成一個主題。",
      "正確，原文寫道「テーマは『平和』と『環境』の二つです。どちらかを選んで応募してください」，須從兩個主題中選一個作畫投稿，符合選項描述。",
      "錯誤，原文明確規定紙張大小為「20×25cm」，並非「喜歡的大小都可以」。",
      "錯誤，原文說明「絵の具、色えんぴつなど、何を使ってかいてもかまいません」，畫具並不限定。"
    ]
