      "sourceNote": "2010年7月為新制JLPT首度以N1-N5分級後的第一次考試，N3自此才成為正式的官方級別（2002-2009年収錄於本專案的是舊制3級考題，比照為N3程度收錄，並非同一官方級別）。來源為重新排版之PDF《2010年7月真题.pdf》（12頁言語知識文字語彙+文法+読解、含頁尾標「第X頁共12頁」的文字層乾淨可選取部分，加上3頁「聴解部分」為掃描全頁圖片、無文字層，以PyMuPDF get_pixmap(dpi=300)配合page.rotation校正橫向頁後裁切局部區塊，人工視覺讀出もんだいI/II的印刷選項文字及もんだいI 1番、もんだいIV 1〜4番的插圖），另有《2010年7月N3听力原文.pdf》（沪江日语绿宝书，聴解五大問題完整逐字稿+もんだい3/4/5的印刷選項文字+官方數字答案）與《2010年7月日本语能力考试N3真题答案解析.pdf》（言語知識文字語彙/文法/読解 逐題中文解析+参考答案，聴解部分亦有逐題中文解析）。三份來源逐題交叉核對：言語知識(文字語彙/文法/読解)部分「参考答案」與逐題中文解析描述之語意完全一致，未發現矛盾。聴解部分：もんだい3/4/5 的「参考答案」數字與其解析描述之選項內容一致；但もんだい1第3題（答案卡標3=ファックス，解析描述卻是「メールで住所を知らせる」對應選項4）、もんだい1第4題（答案卡標2，但對話中「飲み物」「ポスター」均已完成、パソコン由先生負責，唯一尚待學生完成的是「コピー」即選項3，答案卡與解析文字本身也只泛稱「剩下的就是學生要做的」未指名選項內容）、もんだい2第3題（答案卡標3，解析描述「子どもとあそんだこと」實際對應選項2非選項3）、もんだい2第5題（答案卡標2，解析描述之「未使用農藥」等語意實際對應選項4非選項2）共4題的答案卡數字與其自身解析文字描述的選項內容互相矛盾，判斷為此第三方解析PDF本身的印刷/編號錯誤（非本次判讀之誤），已依對話逐字稿語意重新推導出正確答案並保留為bank item，同時在對應item的reviewNote註記此矛盾供未來人工複核；因語意推導把握度高，未標記needsReview排除。もんだい1第6題的原始逐字稿問句寫「男の人はこの後、まず何をしなければなりませんか」，但對話中發出指示的是男性（課長），實際被交辦任務、需要行動的是女性部下，此問句人稱與對話內容不符，研判為聽力原文PDF本身的逐字稿誤植（応為「女の人は」），不影響答案卡數字本身（該題答案卡與其解析文字一致），予以保留並在該item的reviewNote說明此逐字稿人稱瑕疵。もんだいI 2番選項3印刷讀解問題(4)之(3)郵件（鈴木寄給和田的信）在PDF文字層中，信件本文段落因原始版面配置（信件以文字框方式置入）被排版斷開成「あて先/件名」先出現，主文本體卻出現在下一個問題(4)之後──已依內容邏輯重新組合為完整信件段落，非重新編造內容。聴解もんだい1（課題理解）第1題為圖片選項（4款毛衣領口/顏色插圖），もんだいIV（発話表現）全4題為場景插圖，皆取自exam.pdf掃描頁；もんだい2〜3、V全部為純文字選項（聴解原文PDF已印出）。文法問題2「★に入るものはどれですか」延續2010+新制的文の組み立て（詞塊排序）題型，本考卷未見用法(word-usage)類型獨立設置為文法/文字語彙問題5（つかいかたで）已在文字語彙問題5印出、對應type沿用既有'word-usage'。",
