      "prompt": "日本では、1960年ごろから町に道路やビルが次々につくられ、公園や空き地（注）が少しずつ削られてきた。このような町の変化によって、屋外で子供の遊ぶ場所が減少した。そして、子どもの遊び方も変化してきた。昔は子どもは外で遊ぶことが多かったが、今は一人で、室内でテレビを見たり、ゲームをしたりすることが多い。\n　このことは、二つの点で子どもたちに重大な影響を与えた。一つ目は「体力」への影響である。子どもの体力と運動に関する調査では、走る、跳ぶ、投げるなどの基礎的な体力は昔より落ちている。外で体を動かして遊ぶ機会が減ったことが、最大の原因だと考えられている。\n　二つ目は「付き合い方」への影響である。昔は、近所の子どもが一緒に外で遊び、年齢や個人による違いを受け入れて、付き合い方を学習した。しかし、今は部屋で一人で過ごす時間が長くなり、人間関係がうまく作れない子供が増えてしまった。これからも日本の町は発展していくだろうが、それが子供に与える影響も忘れてはいけない。\n\n（注）空き地：建物が建っていない、使われていない土地\n\nこの文章では、子どもに見られる変化には、例えばどんなものがあると言っているか。",
