    "meaning": {
      "prompt": "日本人は、魚をあまり食べなくなり、肉を食べるようになったと言われているが、実際はどうなのだろうか。\n\nある研究所が、料理の材料について男女約1,000人に対して①調査を行った。それによると、1年前に比べて自宅で魚料理を食べることが増えた人は27.0%で、減ったと答えた人は（15.0%）よりかなり多い、魚料理のイメージは「体にいい」が82.7%で、最も多かった。魚は健康にいいという知識が広がっているからだろう。その次は、「おいしい（72.1%）」だった。私は、年をとればとるほど、魚が好きになると思っていたが、②そうではないらしい。魚を「おいしい」と思う人が多い年齢は、60代、20代、30代、50代、40代の順番であった。\n\nこの結果から、日本人は最近また、魚を食べるようになってきていて、若い人にも魚好きが多いということがわかる。\n\nこの文章全体のテーマは、何か。",
      "options": [
        "肉料理を食べる若者",
        "肉好きと年齢の関係",
        "魚料理が嫌いな若者",
        "魚を食べる人の増加"
      ],
      "answerIndex": 3
    },
