    "meaning": {
      "prompt": "最近、仕事の連絡をする時にメールを利用することが多くなりました。メールは時間を選んで読めますから。相手の都合がいいときに相手に読んでもらうことができます。しかし、分かりやすいメールを書くのは意外に難しいものです。読みやすいメールを書くには、どのような工夫が必要でしょうか。\nまず、一行の文字数を多くしないで、短く切って次の行に進むようにしましょう。そして、一つの内容を書き終わったら。次の一行は何も書かないで、その次の行から書き始めます。また、約束の時間や場所など、特に重要なことは、文章の最後にももう一度書いたほうがいい。\n文章を全部書き終わったら、自分の名前と連絡先を書きます。メールで返事をもらうつもりでも、メールアドレスのほかに自分の電話番号とFAX番号も知らせておきましょう。\n\n（メールの例）\n会議の時間と場所が決まりました。4月10日（金）2時から2階の会議室です。テーマは、「社員旅行」です。欠席の人は、山下まで連絡してください。あとで旅行の予定表を送りします。\nでは、4月10日2時に2階の会議室にお集まりください。\n山下ひろみ\nhiromiy@xxx.yyy.co.jp\n電話：03-555-1111\nFAX:03-555-1112\n\nこの文章によると、下のメールはどう直せばいいか。",
      "options": [
        "同じ内容について2回書かない。",
        "一行の長さをもっと短くする。",
        "電話やFAX番号などを書かない。",
        "行と行の間をもっと広くあける。"
      ],
      "answerIndex": 1
    },
    "optionExplanations": [
      "文中並未提到「同じ内容を2回書かない」的規則，例句郵件本身也沒有重複寫兩次同樣內容的問題。",
      "正解。例句郵件第一段每一行的字數偏多，不符合文中「一行の文字数を多くしないで、短く切って次の行に進む」的建議，應把每行長度縮短。",
      "文中提到「メールアドレスのほかに自分の電話番号とFAX番号も知らせておきましょう」，例句郵件已附上電話與FAX，不需要刪除。",
      "文中並未提及「行與行之間要留更大間距」的規則，例句郵件也不存在這個問題。"
    ]
