    "meaning": {
      "prompt": "安見市内のパーティー会場案内\n\n①安見ホール：新しいビルなのできれいです。\n利用時間：8:00〜23:00（定休日：毎月第3月曜日）\n利用人数：最大100名\n利用料金：1時間1,000円\n料理：1人2,000円から（必ず料理を注文してください）\n交通：安見駅から徒歩30分、無料駐車場あり\n\n②花の家：ばらの花で有名な西公園の中にあります。\n利用時間：11:00〜20:00（定休日：木曜日、祝日の場合は水曜日）\n利用人数：10〜50名\n利用料金：無料\n料理：1人1,500円から（飲み物だけの注文でも利用できます）\n交通：安見駅から徒歩15分、西公園に駐車場（有料）あり\n\n③レストラン海　パーティールーム：カラオケが無料で利用できます\n利用時間：11:00〜22:00（定休日：火曜日）、利用は4時間まで\n利用人数：10〜30名\n利用料金：無料\n料理：1人3,000円から（必ず料理を注文してください）\n交通：安見駅から徒歩10分、無料駐車場（15台）あり\n\n④市民センター：コンサートにも使えます。\n利用時間：11:00〜21:00（定休日：月曜日）、利用は4時間まで\n利用人数：最大40名\n利用料金：1時間1,000円\n料理：注文はできません（必要な場合は利用者がご用意ください）\n交通：安見駅から徒歩20分（市役所のとなり）、市役所に駐車場（有料）あり\n\n原さんは、来週の木曜日の午後に読書クラブの活動を行う会場を探している。参加者は30名程度で、料理は必要ないので、飲み物だけ買って持っていきたい。原さんの希望に合う会場はいくつあるか。",
      "options": [
        "1つ",
        "2つ",
        "3つ",
        "4つ"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "正解。原さん的條件是「木曜日の午後」「30名程度」「不需要料理，只想自己買飲料帶去」。①安見ホール的定休日是「毎月第3月曜日」（週一），週四可用，但條件要求「必ず料理を注文してください」，不符合「不需要料理」的要求，故不算。②花の家的定休日是「木曜日」（週四），週四公休，時間不合。③レストラン海的定休日是「火曜日」（週二），週四可用，但同樣要求「必ず料理を注文してください」，不符合。④市民センターの定休日是「月曜日」（週一），週四可用，「料理は注文できません」（不能點餐、需自備），符合「不需要料理，只需自己準備飲料」的需求，且最大40名可容納30名程度。四個會場中只有④符合全部條件，故答案是「1つ」。",
      "見上方解析：只有④市民センター符合全部條件，答案是「1つ」而非「2つ」。",
      "見上方解析：只有④市民センター符合全部條件，答案是「1つ」而非「3つ」。",
      "見上方解析：只有④市民センター符合全部條件，答案是「1つ」而非「4つ」。"
    ]
