      "prompt": "これは、野口さんから山田さんに届いたメールである。\n\n宛先：t.yanada@hokutodenko.co.jp\n件名：会議日程についてのご連絡\n送信日時：2012年11月21日　9:45\n\n北東電気工業　山田様\n\nいつもお世話になっております。\n先週お電話いたしました。新製品に使用する部品についての会議についてが、以下のように決まりました。ご確認ください。\n日時：12月11日（火）14〜16時\n場所：岩丸工業ビル3階会議室\n出席者：田中様（15時よりご参加）、田中様、中川様\n　　金子　野口\nなお、部品のサンプルを郵送しましたので、届きましたらお知らせください。よろしくお願いいたします。\n岩丸工業　野口\n\nこのメールを読んで、山田さんがしなければならないことは何か。",
