      "sourceNote": "轉自《N3-2012-12-真题.pdf》與《N3-2012-12-答案.pdf》（含中文詳解與聴力原文），詳見 src/lib/past-exams/data/jlpt-n3-2012-12.json 的 sourceNote。",
      "questionNumber": "read-VI-34"
