    "meaning": {
      "prompt": "においは、過去の経験をその時の気持ちとともに思い出させることがある。音楽を聞いたり、景色を見たりしたときも同じようなことがあるが、においのほうがもっと強い。においには、何のにおいかと考えさせる前に、体や心を動かす力があるようだ。\n\nにおいの①このような特徴は、いろいろな形で利用される。体や心を休ませたり、集中する力をつけたりするためにも使われるが、最近では次のような利用方法が増えている。例えば、あるスーパーで、人工的に作られたカレーのにおいを売り場に流したら、カレーの材料がいつもより3割ぐらい多く売れたそうだ。においが、その味やそれを食べたときの満足感をはっきりと思い出させ、また食べたいと思わせたからだろう。また、衣類のような、においのしない商品の売り場に、人工的な花のにおいを流している店もあるそうだ。においによって商品のイメージを作ろうとしているのだ。\n\nこれらの話を聞いたときは、においに②そんな使い方があったのかと驚いた。\n\n専門家によると、今ではほとんどのにおいが人工的に作れるそうだ。しかし、人工的なにおいは本当のカレーや花のにおいではない。小学生にある実験をしたら、自然のイチゴのにおいよりも、人工的なイチゴのにおいのほうを本当のイチゴのにおいだと思ってしまう子どもが多かったそうだ。\n\n作られたにおいばかりに固まれていると、それに慣れてしまい、本当のにおいが忘れられていく。人工的なにおいを利用する可能性が広がることはいいことではあるが、本当のにおいも忘れないようにしたい。\n\n①「このような特徴」とあるが、それは何か。",
      "options": [
        "他の感覚よりも強く体や心に影響を与えること",
        "運動したくなるような気持ちにさせること",
        "消費行動を強く起こさせること",
        "何のにおいかを考えさせること"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "正解。文中第一段說明「においには、何のにおいかと考えさせる前に、体や心を動かす力があるようだ」，這種「比起其他感官更能直接影響身心」的特徵，正是①「このような特徴」所指。",
      "「運動したくなるような気持ちにさせること」文中沒有特別提到讓人想運動。",
      "「消費行動を強く起こさせること」這是①之後被提及的「利用方法之一」（例如促進購買咖哩），不是①本身所指的「這樣的特徵」。",
      "「何のにおいかを考えさせること」文中原句是「においを考えさせる前に」（在思考是什麼氣味之前），語意正好相反。"
    ],
